'''Python3 implementation of tree using array
numbering starting from 0 to n-1.'''

tree = [None] * 10

'''create root'''

def root(key):
    if tree[0] != None:
        print("Tree already had root")
    else:
        tree[0] = key

'''create left son of root'''

def set_left(key, parent):
    if tree[parent] == None:
        print("Can't set child at", (parent * 2) + 1, ", no parent found")
    else:
        tree[(parent * 2) + 1] = key

'''create right son of root'''

def set_right(key, parent):
    if tree[parent] == None:
        print("Can't set child at", (parent * 2) + 2, ", no parent found")
    else:
        tree[(parent * 2) + 2] = key

'''Print tree'''

def print_tree():
    for i in range(10):
        if tree[i] != None:
            print(tree[i], end="")
        else:
            print("-", end="")
    print()

'''Driver Code'''

root('A')
set_right('C', 0)
set_left('D', 1)
set_right('E', 1)
set_right('F', 2)
print_tree()

'''Check if each internal
node of BST has only one child'''

def hasOnlyOneChild (pre, size):
    nextDiff=0; lastDiff=0
    for i in range(size-1):
        nextDiff = pre[i] - pre[i+1]
        lastDiff = pre[i] - pre[size-1]
        if nextDiff*lastDiff < 0:
            return False
    return True

'''driver program to
test above function'''

if __name__ == "__main__":
    pre = [8, 3, 5, 7, 6]
    size= len(pre)
    if (hasOnlyOneChild(pre,size) == True):
        print("Yes")
    else:
        print("No")

'''Python3 Program to check
lower triangular matrix.'''

'''Function to check matrix
is in lower triangular'''

def islowertriangular(M):
    for i in range(0, len(M)):
        for j in range(i + 1, len(M)):
            if(M[i][j] != 0):
                    return False
    return True

'''Driver function.'''

M = [[1,0,0,0],
     [1,4,0,0],
     [4,6,2,0],
     [0,4,7,6]]

'''Function call'''

if islowertriangular(M):
    print ("Yes")
else:
    print ("No")

'''Python3 Program to check upper
triangular matrix.
 '''

'''Function to check matrix
is in upper triangular'''

def isuppertriangular(M):
    for i in range(1, len(M)):
        for j in range(0, i):
            if(M[i][j] != 0):
                    return False
    return True

