'''Python code for implementation of Naive Recursive
approach'''

def isPalindrome(x):
    return x == x[::-1]
def minPalPartion(string, i, j):
    if i >= j or isPalindrome(string[i:j + 1]):
        return 0
    ans = float('inf')
    for k in range(i, j):
        count = (
            1 + minPalPartion(string, i, k)
            + minPalPartion(string, k + 1, j)
        )
        ans = min(ans, count)
    return ans

'''Driver code'''

def main():
    string = "ababbbabbababa"
    print(
     "Min cuts needed for Palindrome Partitioning is ",
     minPalPartion(string, 0, len(string) - 1),
    )
if __name__ == "__main__":
    main()

'''minCut function'''

def minCut(a):
    cut = [0 for i in range(len(a))]
    palindrome = [[False for i in range(len(a))] for j in range(len(a))]
    for i in range(len(a)):
        minCut = i;
        for j in range(i + 1):
            if (a[i] == a[j] and (i - j < 2 or palindrome[j + 1][i - 1])):      
                palindrome[j][i] = True;
                minCut = min(minCut,0 if  j == 0 else (cut[j - 1] + 1));
        cut[i] = minCut;  
    return cut[len(a) - 1];

'''Driver code'''

if __name__=='__main__':
    print(minCut("aab"))
    print(minCut("aabababaxx"))

'''Returns the new average
after including x'''

def getAvg(prev_avg, x, n):
    return ((prev_avg *
             n + x) /
            (n + 1));

'''Prints average of
a stream of numbers'''

def streamAvg(arr, n):
    avg = 0;
    for i in range(n):
        avg = getAvg(avg, arr[i], i);
        print("Average of ", i + 1,
              " numbers is ", avg);

'''Driver Code'''

arr = [10, 20, 30,
       40, 50, 60];
n = len(arr);
streamAvg(arr, n);

'''Returns the new average
after including x'''

def getAvg(x, n, sum):
    sum = sum + x;
    return float(sum) / n;

'''Prints average of a
stream of numbers'''

def streamAvg(arr, n):
    avg = 0;
    sum = 0;
    for i in range(n):
        avg = getAvg(arr[i], i + 1, sum);
        sum = avg * (i + 1);
        print("Average of ", end = "");
        print(i + 1, end = "");
        print(" numbers is ", end = "");
        print(avg);
    return;

'''Driver Code'''

arr= [ 10, 20, 30,
       40, 50, 60 ];
n = len(arr);
streamAvg(arr,n);

'''Efficient Python3 program to
find smallest greater element
in whole array for every element'''

def smallestGreater(arr, n):

    s = set()

    for i in range(n):
        s.add(arr[i])

    newAr = []

    for p in s:
        newAr.append(p)

    for i in range(n):
        temp = lowerBound(newAr, 0, len(newAr),
                          arr[i])

        if (temp < n):
            print(newAr[temp], end = " ")
        else:
            print("_ ", end = "")

'''lowerbound function'''

def lowerBound(vec, low, high, element):

    array = [0] * (len(vec))

    k = 0

    for val in vec:
        array[k] = val
        k += 1
    while (low < high):
        middle = low + int((high - low) / 2)

        if (element > array[middle]):
            low = middle + 1
        else:
            high = middle

    return low + 1

'''Driver code'''

if __name__ == '__main__':

    ar = [ 6, 3, 9, 8, 10, 2, 1, 15, 7 ]
    n = len(ar)

    smallestGreater(ar, n)

def minswaps(arr):
    count = 0
    num_unplaced_zeros = 0

    for index in range(len(arr)-1, -1, -1):
        if arr[index] == 0:
            num_unplaced_zeros += 1
        else:
            count += num_unplaced_zeros
    return count

'''Driver Code'''


arr = [0, 0, 1, 0, 1, 0, 1, 1]
print(minswaps(arr))

'''Python3 code to Find the repeating
and the missing elements'''


def printTwoElements( arr, size):
    for i in range(size):
        if arr[abs(arr[i])-1] > 0:
            arr[abs(arr[i])-1] = -arr[abs(arr[i])-1]
        else:
            print("The repeating element is", abs(arr[i]))

    for i in range(size):
        if arr[i]>0:
            print("and the missing element is", i + 1)

'''Driver program to test above function */'''

arr = [7, 3, 4, 5, 5, 6, 2]
n = len(arr)
printTwoElements(arr, n)

'''Python3 program to find the
repeating and missing elements
using Maps'''

def main():

    arr = [ 4, 3, 6, 2, 1, 1 ]

    numberMap = {}

    max = len(arr)
    for i in arr:
        if not i in numberMap:
            numberMap[i] = True

        else:
            print("Repeating =", i)

    for i in range(1, max + 1):
        if not i in numberMap:
            print("Missing =", i)
main()

'''Python3 program for the above approach'''

'''Function to left rotate'''

def left_rotate(arr):

    last = arr[1];
    for i in range(3, len(arr), 2):
        arr[i - 2] = arr[i]

    arr[len(arr) - 1] = last

'''Function to right rotate'''

def right_rotate(arr):

    start = arr[len(arr) - 2]
    for i in range(len(arr) - 4, -1, -2):
        arr[i + 2] = arr[i]

    arr[0] = start

'''Function to rotate the array'''

def rotate(arr):

    left_rotate(arr)
    right_rotate(arr)
    for i in range(len(arr)):
        print(arr[i], end = " ")

'''Driver code'''

arr = [ 1, 2, 3, 4, 5, 6 ]

rotate(arr);
